def step(id, la, it, en, dip, mostra, evidenzia=None, nota=None):
    d = {"id": id, "la": la, "it": it, "en": en, "dipende_da": dip,
         "figura": {"mostra": mostra}}
    if evidenzia: d["figura"]["evidenzia"] = evidenzia
    if nota: d["nota"] = nota
    return d

